mapper.select:
SELECT num, admin_num, title, CONTENT, imgn, hit, created_date, updated_date, row_num FROM
(SELECT num, admin_num, title, CONTENT, imgn, hit, created_date, updated_date, ROW_NUMBER()
OVER(ORDER BY num desc) AS row_num FROM notice




				title like '%' || #{searchValue} || '%'


				content like '%' || #{searchValue} || '%'




) numbered_rows WHERE row_num BETWEEN #{begin} AND #{end}

mapper.update:
UPDATE notice
SET title = #{title}, content = #{content}, imgn = #{imgn}, updated_date = SYSDATE
WHERE num = #{num}
